    public Gadomancy(){
        RevivalFeatures.register();net.minecraftforge.fml.ModLoadingContext.get().registerConfig(net.minecraftforge.fml.config.ModConfig.Type.CLIENT,ClientConfig.SPEC);var bus=FMLJavaModLoadingContext.get().getModEventBus();bus.addListener((net.minecraftforge.fml.event.lifecycle.FMLCommonSetupEvent event)->event.enqueueWork(gadomancymodern.node.NodeCaptureIntegration::setup));ITEMS.register(bus);TABS.register(bus);BLOCKS.register(bus);BLOCK_ENTITIES.register(bus);MENUS.register(bus);ENTITIES.register(bus);RECIPES.register(bus);ENCHANTMENTS.register(bus);gadomancymodern.aura.GadEffects.EFFECTS.register(bus);net.minecraftforge.fml.ModLoadingContext.get().registerConfig(net.minecraftforge.fml.config.ModConfig.Type.COMMON,gadomancymodern.aura.AuraEffectsConfig.SPEC);bus.addListener((net.minecraftforge.fml.event.lifecycle.FMLCommonSetupEvent event)->event.enqueueWork(gadomancymodern.aura.StandardAuraEffects::register));
        gadomancymodern.disguise.DisguiseIngredient.register();gadomancymodern.disguise.DisguiseNetwork.register();gadomancymodern.golem.GadGolems.register();
        gadomancymodern.maze.MazeSessions.register();net.minecraftforge.common.crafting.CraftingHelper.register(new gadomancymodern.node.GadConfigCondition.Serializer());
        thaumcraft.api.research.ResearchCategories.registerEnablement("gadomancy:ancient_stones",()->gadomancymodern.aura.AuraEffectsConfig.ANCIENT_STONES.get());
        for(String key:java.util.List.of("growing","growing_aggression","growing_growth","growing_attack","growing_growthclue"))thaumcraft.api.research.ResearchCategories.registerEnablement("gadomancy:"+key,()->gadomancymodern.aura.AuraEffectsConfig.ADDITIONAL_NODES.get());
        gadomancymodern.node.NodeVisualNetwork.register();tc4revival.content.RevealingGear.registerProvider(net.minecraft.resources.ResourceLocation.parse("gadomancy:revealer"),(entity,nodes)->gadomancymodern.enchantment.RevealerEnchantment.active(entity));
        gadomancymodern.familiar.FamiliarRecipes.register(bus);gadomancymodern.familiar.FamiliarNetwork.register();
        bus.addListener((net.minecraftforge.event.entity.EntityAttributeCreationEvent event)->event.put(SILVERWOOD_ENTITY.get(),tc4revival.content.GolemEntity.attributes().build()));
        thaumcraft.api.research.ResearchPrerequisites.conditional(net.minecraft.resources.ResourceLocation.parse("gadomancy:remote_jar_mirror"),"gadomancy:remote_jar","MIRRORESSENTIA",()->tc4revival.config.TCConfig.SERVER.allowMirrors.get());
        thaumcraft.api.research.ResearchPrerequisites.conditional(new net.minecraft.resources.ResourceLocation(MOD_ID,"packager_warded_glass"),"gadomancy:arcane_packager","WARDEDARCANA",()->tc4revival.config.TCConfig.SERVER.wardedStone.get());
    }
    static {TABS.register("main",()->CreativeModeTab.builder().title(Component.literal("Gadomancy")).icon(()->new ItemStack(CATEGORY_ICON.get()))
        .displayItems((parameters,output)->{gadomancymodern.item.CreativeNodeItem.variants(CREATIVE_NODE.get()).forEach(output::accept);output.accept(MANIPULATOR_ITEM.get());output.accept(RANDOMIZATION_FOCUS_ITEM.get());output.accept(PORTAL_FOCUS_ITEM.get());output.accept(ADDITIONAL_PORTAL_ITEM.get());output.accept(COMPRESSOR_ITEM.get());output.accept(ANCIENT_PEDESTAL_ITEM.get());output.accept(DARKNESS_ELEMENT.get());output.accept(PYLON_ITEM.get());output.accept(PYLON_CAP_ITEM.get());output.accept(CLAW_ITEM.get());output.accept(PACKAGE.get());output.accept(DISGUISED_PACKAGE.get());output.accept(PACKAGER_ITEM.get());output.accept(DROPPER_ITEM.get());output.accept(PROTECTOR_ITEM.get());output.accept(REMOTE_JAR_ITEM.get());output.accept(KNOWLEDGE_BOOK_ITEM.get());output.accept(SILVERWOOD_GOLEM.get());output.accept(BREAK_CORE.get());output.accept(BODYGUARD_CORE.get());gadomancymodern.item.EtherealFamiliarItem.creative(ETHEREAL_FAMILIAR.get()).forEach(output::accept);AURA_CORES.values().forEach(item->output.accept(item.get()));for(var jar:java.util.List.of(tc4revival.content.TCItems.ESSENTIA_JAR.get(),tc4revival.content.TCItems.VOID_JAR.get())){var stack=new ItemStack(jar);stack.getOrCreateTag().putBoolean("isStickyJar",true);output.accept(stack);}}).build());}
